<?php
declare(strict_types=1);
// Destructive restore tests are restricted to an existing disposable test database.
$name=getenv('TEST_DB_NAME')?:'webshop_test';if(!preg_match('/^webshop_test(?:_[a-z0-9]+)?$/D',$name))exit("Refusing non-test database.\n");
$root=dirname(__DIR__);foreach(['config/local.php','config/backup.key','config/mail.key','storage/maintenance.flag'] as $file)if(file_exists($root.'/'.$file))exit('Refusing existing '.$file."\n");
$db=new PDO('mysql:host='.(getenv('TEST_DB_HOST')?:'127.0.0.1').';port='.(getenv('TEST_DB_PORT')?:'33317').';dbname='.$name.';charset=utf8mb4',getenv('TEST_DB_USER')?:'root',getenv('TEST_DB_PASSWORD')?:'local_test_only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
require $root.'/app/services.php';$_SESSION=['user_id'=>1];if(backupList())exit("Refusing existing backups.\n");
function checkBackup(bool $condition,string $message):void {if(!$condition)throw new RuntimeException('FAIL: '.$message);echo 'PASS: '.$message."\n";}
$epochBefore=is_file($root.'/storage/session-epoch')?file_get_contents($root.'/storage/session-epoch'):null;$work=null;$extraPhoto=$root.'/public/uploads/'.str_repeat('f',32).'.png';if(file_exists($extraPhoto))exit("Refusing existing test photo.\n");$mailKey=random_bytes(32);file_put_contents($root.'/config/mail.key',$mailKey);
try{
    $original=query('SELECT * FROM products ORDER BY id LIMIT 1')->fetch();$id=backupCreate();$manifest=backupInspect($id);checkBackup(count($manifest['tables'])===((brandsReady()?19:18)+(partnersReady()?6:0)),'full application table set saved and verified');checkBackup(is_file($root.'/config/backup.key')&&substr(file_get_contents(backupRoot().'/'.$id.'.wsb'),0,4)==='WSB1','backup is encrypted and local recovery key separate');
    query("UPDATE products SET name='Changed after backup',price=999.00 WHERE id=?",[$original['id']]);file_put_contents($extraPhoto,'test extra photo');file_put_contents($root.'/config/mail.key',random_bytes(32));
    $work=backupWork();$bytes=file_get_contents(backupRoot().'/'.$id.'.wsb');$bytes[60]=chr(ord($bytes[60])^1);file_put_contents($work.'/tampered.wsb',$bytes);
    try{backupImport($work.'/tampered.wsb');checkBackup(false,'corrupt backup rejected');}catch(RuntimeException){checkBackup(query('SELECT name FROM products WHERE id=?',[$original['id']])->fetchColumn()==='Changed after backup','corrupt archive rejected before changing data');}
    $key=file_get_contents($root.'/config/backup.key');file_put_contents($root.'/config/backup.key',random_bytes(32));try{backupInspect($id);checkBackup(false,'wrong key rejected');}catch(RuntimeException){checkBackup(true,'wrong recovery key rejected');}finally{file_put_contents($root.'/config/backup.key',$key);}
    $safety=backupRestore($id);$restored=query('SELECT * FROM products WHERE id=?',[$original['id']])->fetch();checkBackup($restored['name']===$original['name']&&$restored['price']===$original['price'],'restore replaces changed database rows with original values');checkBackup(!is_file($extraPhoto)&&file_get_contents($root.'/config/mail.key')===$mailKey,'photos and SMTP key restored with database');checkBackup(!is_file($root.'/storage/maintenance.flag'),'maintenance cleared after successful restore');checkBackup(is_file(backupRoot().'/'.$safety.'.wsb')&&backupInspect($safety)['reason']==='before_restore','automatic safety copy retained before restore');checkBackup((int)query("SELECT COUNT(*) FROM mail_jobs WHERE status IN ('pending','failed')")->fetchColumn()===0,'old queued emails suspended after restore');
    $imported=backupImport(backupRoot().'/'.$id.'.wsb');checkBackup(backupInspect($imported)['format']===1,'downloaded format can be imported and validated');
    // Forge an authenticated test archive with a duplicate primary key to exercise transaction rollback.
    $opened=backupOpen($id);$m=$opened['manifest'];$file='tables/products.jsonl';$rows=file_get_contents($opened['work'].'/tables_products.jsonl');$first=strtok($rows,"\n");$rows.=$first."\n";$m['tables']['products']['rows']++;$m['files'][$file]=['size'=>strlen($rows),'sha256'=>hash('sha256',$rows)];$zip=new ZipArchive();$zip->open($opened['work'].'/archive.zip');$zip->addFromString($file,$rows);$zip->addFromString('manifest.json',json_encode($m,JSON_THROW_ON_ERROR));$zip->close();backupCrypt($opened['work'].'/archive.zip',$work.'/duplicate.wsb',$key);backupClean($opened['work']);$invalid=backupImport($work.'/duplicate.wsb');
    query("UPDATE products SET name='Must survive failed restore' WHERE id=?",[$original['id']]);try{backupRestore($invalid);checkBackup(false,'invalid row restore must fail');}catch(PDOException){checkBackup(query('SELECT name FROM products WHERE id=?',[$original['id']])->fetchColumn()==='Must survive failed restore','failed database insertion rolls back all restored rows');checkBackup(!is_file($root.'/storage/maintenance.flag'),'failed restore clears maintenance and keeps current files');}
    query('UPDATE products SET name=? WHERE id=?',[$original['name'],$original['id']]);checkBackup((int)query('SELECT @@FOREIGN_KEY_CHECKS')->fetchColumn()===1,'foreign key checks re-enabled after success and failure');

    // Simulate a killed process after the photo swap, but before database commit.
    $stage=backupWork();$staleWork=backupWork();rename($root.'/public/uploads',$stage.'/old-uploads');mkdir($root.'/public/uploads');file_put_contents($extraPhoto,'Interrupted replacement');$operation=bin2hex(random_bytes(16));file_put_contents(backupRoot().'/.restore.json',json_encode(['operation'=>$operation,'stage'=>$stage,'work'=>$staleWork,'mail_before'=>base64_encode($mailKey)]));file_put_contents($root.'/storage/maintenance.flag','Test interrupted restore');checkBackup(backupRecoverInterrupted()&&!is_file($extraPhoto)&&is_file($root.'/public/uploads/.htaccess'),'interrupted uncommitted restore recovers original files automatically');
    $stage=backupWork();mkdir($stage.'/old-uploads');$staleWork=backupWork();$operation=bin2hex(random_bytes(16));query("INSERT INTO audit_log(user_id,action,details) VALUES(NULL,'backup.restored',?)",['Test oporavak '.$operation]);file_put_contents(backupRoot().'/.restore.json',json_encode(['operation'=>$operation,'stage'=>$stage,'work'=>$staleWork,'mail_before'=>base64_encode($mailKey)]));file_put_contents($root.'/storage/maintenance.flag','Test committed restore');checkBackup(backupRecoverInterrupted()&&!is_file($root.'/storage/maintenance.flag'),'interrupted committed restore keeps restored data and completes cleanup');
}finally{
    if($epochBefore===null)@unlink($root.'/storage/session-epoch');else file_put_contents($root.'/storage/session-epoch',$epochBefore);if($work)backupClean($work);foreach(backupList() as $copy){$id=backupId($copy['id']);unlink(backupRoot().'/'.$id.'.wsb');unlink(backupRoot().'/'.$id.'.json');}foreach(['config/backup.key','config/mail.key'] as $file)if(is_file($root.'/'.$file))unlink($root.'/'.$file);if(is_file($extraPhoto))unlink($extraPhoto);
}
